mapper.select:
SELECT M.MATCHING_NO, M.MATCHING_TITLE, M.MATCHING_CONTENT, M.MATCHING_LOCATION, M.MATCHING_TIME, M.USER_NO, M.CREATED_AT, M.PARTNER_TYPE, M.MATCHING_USER_COUNT, M.MATCHING_PRICE, M.LONGITUDE, M.LATITUDE, M.LOCATION_URL, U.USER_NAME, PER.CAREER, PER.CAREER_DETAIL, U.USER_PHONE, (SELECT COUNT(*) FROM MATCHING_APPLI_TBL AT WHERE AT.MATCHING_NO = M.MATCHING_NO ) AS APPLYCOUNT,
(SELECT IMG_PATH || '/' || IMG_RENAME FROM USER_PROFILE_IMG_TBL WHERE USER_NO = M.USER_NO AND IMG_MAIN = 'Y' AND ROWNUM = 1) AS USER_PROFILE_IMG, CASE WHEN (SELECT COUNT(*) FROM MATCHING_APPLI_TBL WHERE MATCHING_NO = M.MATCHING_NO) >= M.MATCHING_USER_COUNT THEN '마감'
WHEN (M.MATCHING_USER_COUNT - (SELECT COUNT(*) FROM MATCHING_APPLI_TBL WHERE MATCHING_NO = M.MATCHING_NO)) <= 2 THEN '마감임박' ELSE '모집중' END AS MATCHING_STATUS FROM MATCHING_TBL M JOIN USER_TBL U ON M.USER_NO = U.USER_NO JOIN REQUEST_PERMISSION PER ON M.USER_NO = PER.USER_NO WHERE M.DELETE_YN = 'N' AND M.MATCHING_TYPE = 'TRAINER' AND M.MATCHING_NO = #{matchingNo}

